cat > /app/output/styles.css << 'EOF'
:root {
  --bg: #131423;
  --bg-elev: #1a1a2e;
  --bg-soft: #20233a;
  --line: #2a2f4c;
  --text: #e8ecff;
  --muted: #98a2c6;
  --blue: #2962ff;
  --teal: #14b8a6;
  --green: #22c55e;
  --red: #f7525f;
  --yellow: #fbbf24;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: "DM Sans", "Inter", system-ui, sans-serif;
  background: radial-gradient(circle at 10% -20%, #2f3564 0%, transparent 30%), var(--bg);
  color: var(--text);
}
a { color: inherit; text-decoration: none; }
.container { max-width: 1380px; margin: 0 auto; padding: 0 16px; }
.topbar {
  position: sticky; top: 0; z-index: 30;
  backdrop-filter: blur(10px);
  background: rgba(19, 20, 35, 0.86);
  border-bottom: 1px solid var(--line);
}
.nav { display: flex; align-items: center; gap: 14px; min-height: 64px; }
.brand { font-weight: 800; letter-spacing: .2px; color: #fff; }
.brand .dot { color: var(--blue); }
.nav-links { display: flex; gap: 4px; flex-wrap: wrap; }
.nav-link {
  padding: 8px 12px; border-radius: 8px; color: var(--muted); font-weight: 600; font-size: 14px;
}
.nav-link.active, .nav-link:hover { color: #fff; background: var(--bg-soft); }
.btn {
  border: 1px solid var(--line); background: var(--bg-soft); color: #fff;
  padding: 9px 12px; border-radius: 8px; cursor: pointer; font-weight: 700;
}
.btn.primary { background: linear-gradient(135deg, var(--blue), var(--teal)); border: none; }
.spacer { flex: 1; }
.hero {
  display: grid; grid-template-columns: 1.6fr 1fr; gap: 16px; margin-top: 16px;
}
.panel {
  background: linear-gradient(160deg, rgba(255,255,255,.02), transparent), var(--bg-elev);
  border: 1px solid var(--line); border-radius: 12px; padding: 14px;
}
h1 { margin: 6px 0 8px; font-size: 32px; line-height: 1.12; }
h2 { margin: 0 0 10px; font-size: 19px; }
h3 { margin: 0 0 8px; font-size: 14px; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; }
p { margin: 0; color: #cdd3ee; }
.row { display: flex; gap: 8px; align-items: center; }
.grid { display: grid; gap: 12px; }
.grid.two { grid-template-columns: 1fr 1fr; }
.grid.three { grid-template-columns: repeat(3, 1fr); }
.grid.four { grid-template-columns: repeat(4, 1fr); }
.stat {
  padding: 10px; border: 1px solid var(--line); border-radius: 10px; background: #171a31;
}
.label { font-size: 12px; color: var(--muted); margin-bottom: 4px; }
.value { font-size: 18px; font-weight: 700; }
.pos { color: var(--green); }
.neg { color: var(--red); }
.badge {
  font-size: 12px; font-weight: 700; padding: 3px 7px; border-radius: 999px;
  border: 1px solid var(--line); background: #1b1e37; color: #fff;
}
.tabs { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; }
.tab {
  padding: 7px 10px; border-radius: 8px; border: 1px solid var(--line); background: #181b33;
  color: #b3bcde; cursor: pointer; font-size: 12px; font-weight: 700;
}
.tab.active { background: #22315f; color: #fff; border-color: #355097; }
.table { width: 100%; border-collapse: collapse; font-size: 13px; }
.table th, .table td { padding: 8px 6px; border-bottom: 1px solid var(--line); text-align: left; }
.table th { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: .07em; }
.spark { height: 34px; display: flex; align-items: end; gap: 3px; }
.spark span { width: 5px; background: #3f73ff; border-radius: 3px 3px 0 0; }
.layout-chart { display: grid; grid-template-columns: 280px 1fr 330px; gap: 12px; margin-top: 16px; }
.watch-group { margin-bottom: 8px; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.watch-header { cursor: pointer; background: #1a1d34; padding: 8px 10px; font-weight: 700; font-size: 13px; }
.watch-body { display: none; }
.watch-group.open .watch-body { display: block; }
.watch-item { padding: 8px 10px; border-top: 1px solid var(--line); font-size: 13px; display: flex; justify-content: space-between; }
.toolbar { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }
.chart-canvas {
  height: 420px; border: 1px solid var(--line); border-radius: 10px; background: linear-gradient(180deg, #13182e, #101425);
  position: relative; overflow: hidden;
}
.candle { position: absolute; width: 8px; border-radius: 2px; }
.wick { position: absolute; width: 2px; background: #9ba6d0; left: 3px; }
.feed-item { padding: 10px; border: 1px solid var(--line); border-radius: 10px; background: #181a31; margin-bottom: 8px; }
.rating { color: var(--yellow); }
@media (max-width: 1100px) {
  .layout-chart { grid-template-columns: 1fr; }
  .hero, .grid.four, .grid.three { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 760px) {
  .hero, .grid.two, .grid.three, .grid.four { grid-template-columns: 1fr; }
  h1 { font-size: 26px; }
}
EOF

cat > /app/output/app.js << 'EOF'
const $ = (s, p = document) => p.querySelector(s);
const $$ = (s, p = document) => [...p.querySelectorAll(s)];

function wireTabs(scope = document) {
  $$('[data-tabset]', scope).forEach((set) => {
    const buttons = $$('[data-tab]', set);
    const panels = $$('[data-panel]', set);
    buttons.forEach((btn) => {
      btn.addEventListener('click', () => {
        const key = btn.dataset.tab;
        buttons.forEach((b) => b.classList.toggle('active', b === btn));
        panels.forEach((panel) => {
          panel.style.display = panel.dataset.panel === key ? '' : 'none';
        });
      });
    });
  });
}

function wireWatchAccordion() {
  $$('.watch-header').forEach((header) => {
    header.addEventListener('click', () => {
      header.parentElement.classList.toggle('open');
    });
  });
}

function wireTimeframe() {
  const map = {
    '1D': [38,20,30,18,40,26,31,16,24,34,22,29,17,27,23],
    '5D': [20,21,22,24,23,25,22,26,27,28,26,29,31,30,33],
    '1M': [14,18,17,21,23,20,24,22,26,29,31,30,32,35,36],
    '3M': [12,15,18,17,22,24,28,26,30,29,32,34,31,36,38],
    '6M': [10,13,14,18,20,19,24,25,23,27,30,33,35,37,39],
    'YTD': [8,11,13,14,18,21,20,25,28,27,31,34,36,40,42],
    '1Y': [6,10,12,11,15,18,17,21,24,23,27,29,33,35,39],
    '5Y': [4,6,8,10,9,12,14,16,18,22,26,30,34,38,43],
    'All': [3,5,6,8,7,11,13,15,17,19,23,27,31,37,44]
  };
  const container = $('#chart-bars');
  if (!container) return;
  const draw = (arr) => {
    container.innerHTML = '';
    arr.forEach((h, i) => {
      const wick = document.createElement('div');
      wick.className = 'wick';
      wick.style.left = `${22 + i * 20}px`;
      wick.style.top = `${130 - (h + 9)}px`;
      wick.style.height = `${h + 18}px`;
      container.appendChild(wick);

      const c = document.createElement('div');
      c.className = 'candle';
      c.style.left = `${19 + i * 20}px`;
      c.style.top = `${150 - h}px`;
      c.style.height = `${h}px`;
      c.style.background = i % 3 === 0 ? '#f7525f' : '#22c55e';
      container.appendChild(c);
    });
  };
  draw(map['1D']);
  $$('[data-time]').forEach((btn) => {
    btn.addEventListener('click', () => {
      $$('[data-time]').forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      draw(map[btn.dataset.time] || map['1D']);
    });
  });
}

function wireVideoOnly() {
  const toggle = $('#videosOnly');
  const items = $$('.idea-item');
  if (!toggle || !items.length) return;
  toggle.addEventListener('change', () => {
    items.forEach((item) => {
      const isVideo = item.dataset.video === 'true';
      item.style.display = toggle.checked ? (isVideo ? '' : 'none') : '';
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  wireTabs();
  wireWatchAccordion();
  wireTimeframe();
  wireVideoOnly();
});
EOF

